insert into public.quote_templates(name) values ('Füvesítés termőföld rátöltéssel') on conflict(name) do nothing;
insert into public.quote_templates(name) values ('Füvesítés rotakapálással, komposzttal') on conflict(name) do nothing;
insert into public.quote_templates(name) values ('Járda építés') on conflict(name) do nothing;
insert into public.quote_template_items(template_id,position,catalog_id,category,subcategory) select t.id,1,c.id,'Füvesités','Gyomirtás' from public.quote_templates t left join lateral (select id from public.quote_price_catalog where subcategory='Gyomirtás' order by source_row limit 1) c on true where t.name='Füvesítés termőföld rátöltéssel' and not exists(select 1 from public.quote_template_items x where x.template_id=t.id and x.position=1);
insert into public.quote_template_items(template_id,position,catalog_id,category,subcategory) select t.id,2,c.id,'Termőföld','Anyagbeszerzés 2m3' from public.quote_templates t left join lateral (select id from public.quote_price_catalog where subcategory='Anyagbeszerzés 2m3' order by source_row limit 1) c on true where t.name='Füvesítés termőföld rátöltéssel' and not exists(select 1 from public.quote_template_items x where x.template_id=t.id and x.position=2);
